"use client";

import React, { useState, useEffect, useRef, useCallback } from "react";
import dynamic from "next/dynamic";
import VoiceAgent from "@/components/VoiceAgent";
import type { LatLngTuple } from "@/components/RiderMap";
import {
  ShieldAlert,
  Headphones,
  Check,
  Power,
  Navigation,
  Zap,
  Clock,
  Sun,
  AlertOctagon,
  ChevronRight,
  ShieldCheck,
  MapPin,
} from "lucide-react";

// ----------------------------------------------------------------
// Leaflet requires window/document → load with ssr:false inside a
// Client Component (this file is already 'use client').
// ----------------------------------------------------------------
const RiderMap = dynamic(() => import("@/components/RiderMap"), {
  ssr: false,
  loading: () => (
    <div className="w-full rounded-2xl border-2 border-neutral-800 bg-neutral-950 flex items-center justify-center text-neutral-400 text-xs font-mono" style={{ height: "280px" }}>
      <span className="animate-pulse">Loading Map…</span>
    </div>
  ),
});

const Speedometer = dynamic(() => import("@/components/Speedometer"), {
  ssr: false,
  loading: () => (
    <div className="w-full rounded-2xl border-2 border-neutral-800 bg-black h-36 flex items-center justify-center text-neutral-400 text-xs font-mono animate-pulse">
      Acquiring GPS…
    </div>
  ),
});

// Demo route: Kolkata city centre → Howrah Bridge (illustrative polyline)
const DEMO_ROUTE: LatLngTuple[] = [
  [22.5726, 88.3639], // Kolkata city centre
  [22.5744, 88.3568], // heading west
  [22.577, 88.3487], // mid route
  [22.5851, 88.3425], // near Howrah Bridge south
  [22.5867, 88.3401], // Howrah Bridge
];

export default function RiderDashboard() {
  // ── Pre-ride state ───────────────────────────────────────────────
  const [isRideActive, setIsRideActive] = useState<boolean>(false);
  const [ambientModeConfirmed, setAmbientModeConfirmed] = useState<boolean>(false);
  const [wakeLockActive, setWakeLockActive] = useState<boolean>(false);

  // ── Active HUD state ─────────────────────────────────────────────
  const [currentTime, setCurrentTime] = useState<string>("");
  const [currentDestination, setCurrentDestination] = useState<string>("Tap earphone button to set route");
  const [highContrastMode, setHighContrastMode] = useState<boolean>(true);
  const [liveSpeedKmh, setLiveSpeedKmh] = useState<number>(0);
  const [showRoute, setShowRoute] = useState<boolean>(false);

  const wakeLockSentinelRef = useRef<any>(null);

  // ── Clock ────────────────────────────────────────────────────────
  useEffect(() => {
    const tick = () =>
      setCurrentTime(
        new Date().toLocaleTimeString("en-IN", {
          hour: "2-digit",
          minute: "2-digit",
          hour12: true,
        })
      );
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  // ── Wake Lock ────────────────────────────────────────────────────
  const requestScreenWakeLock = useCallback(async () => {
    if (typeof window === "undefined") return;
    if (!("wakeLock" in navigator) || !navigator.wakeLock) return;
    try {
      const sentinel = await navigator.wakeLock.request("screen");
      wakeLockSentinelRef.current = sentinel;
      setWakeLockActive(true);
      sentinel.addEventListener("release", () => setWakeLockActive(false));
      console.log("[WakeLock] Acquired.");
    } catch (err) {
      console.warn("[WakeLock] Could not acquire:", err);
    }
  }, []);

  const releaseScreenWakeLock = useCallback(() => {
    try { wakeLockSentinelRef.current?.release(); } catch { }
    wakeLockSentinelRef.current = null;
    setWakeLockActive(false);
  }, []);

  // Re-acquire if page becomes visible again mid-ride
  useEffect(() => {
    const onVisible = async () => {
      if (document.visibilityState === "visible" && isRideActive) {
        await requestScreenWakeLock();
      }
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => document.removeEventListener("visibilitychange", onVisible);
  }, [isRideActive, requestScreenWakeLock]);

  useEffect(() => () => releaseScreenWakeLock(), [releaseScreenWakeLock]);

  // ── Ride start / end ────────────────────────────────────────────
  const handleStartRide = async () => {
    if (!ambientModeConfirmed) return;
    if (typeof window !== "undefined" && "vibrate" in navigator) navigator.vibrate([100, 50, 100]);
    await requestScreenWakeLock();
    setIsRideActive(true);
  };

  const handleEndRide = () => {
    if (typeof window !== "undefined" && "vibrate" in navigator) navigator.vibrate(200);
    releaseScreenWakeLock();
    setIsRideActive(false);
    setAmbientModeConfirmed(false);
    setShowRoute(false);
  };

  const handleDestinationFound = (destination: string) => {
    setCurrentDestination(destination);
    // Show the demo route when a destination is confirmed
    setShowRoute(true);
  };

  return (
    <main
      className={`min-h-screen w-full flex flex-col transition-colors duration-200 ${highContrastMode ? "bg-black text-white" : "bg-neutral-950 text-neutral-100"
        }`}
    >
      {/* =========================================================== */}
      {/* PHASE 1: MANDATORY PRE-RIDE SAFETY ONBOARDING               */}
      {/* =========================================================== */}
      {!isRideActive ? (
        <div className="flex-1 flex flex-col justify-between max-w-lg mx-auto w-full p-5 sm:p-7">
          <div>
            {/* Brand header */}
            <div className="flex items-center justify-between pt-2 pb-6 border-b border-neutral-800">
              <div className="flex items-center gap-2.5">
                <div className="w-10 h-10 rounded-xl bg-[#00ff88] text-black font-black flex items-center justify-center text-xl shadow-[0_0_20px_rgba(0,255,136,0.5)]">
                  VS
                </div>
                <div>
                  <h1 className="text-xl font-extrabold tracking-tight text-white leading-none">
                    VoiceSarathi
                  </h1>
                  <span className="text-[11px] font-mono text-[#00ff88] tracking-widest uppercase">
                    Smart Helmet HUD
                  </span>
                </div>
              </div>
              <div className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-neutral-900 border border-neutral-700 text-xs font-mono text-neutral-300">
                <Clock className="w-3.5 h-3.5 text-neutral-400" />
                <span>{currentTime || "00:00"}</span>
              </div>
            </div>

            {/* Safety callout */}
            <div className="mt-6 p-4 rounded-2xl bg-amber-500/10 border-2 border-amber-500/80 text-amber-200">
              <div className="flex items-start gap-3">
                <ShieldAlert className="w-7 h-7 text-amber-400 flex-shrink-0 mt-0.5" />
                <div>
                  <h2 className="text-base font-bold text-amber-300 uppercase tracking-wide">
                    Mandatory Rider Protocol
                  </h2>
                  <p className="text-xs text-amber-100/90 mt-1 leading-relaxed">
                    VoiceSarathi is a zero-touch audio HUD. Never look at or touch your phone
                    while in traffic. Confirm your earphone transparency mode is enabled below.
                  </p>
                </div>
              </div>
            </div>

            {/* Feature chips */}
            <div className="mt-6 space-y-3">
              {[
                {
                  icon: <Headphones className="w-4 h-4" />,
                  color: "text-[#00f0ff]",
                  title: "Earphone Button Hijack",
                  desc: "Single press = Bengali voice command.",
                },
                {
                  icon: <Zap className="w-4 h-4" />,
                  color: "text-[#ffee00]",
                  title: "Screen Wake Lock",
                  desc: "Display stays on during your entire ride.",
                },
                {
                  icon: <MapPin className="w-4 h-4" />,
                  color: "text-[#ff88cc]",
                  title: "Live Leaflet Map",
                  desc: "Dark-themed OpenStreetMap with route polyline.",
                },
              ].map(({ icon, color, title, desc }) => (
                <div
                  key={title}
                  className="p-3.5 rounded-xl bg-neutral-900/90 border border-neutral-800 flex items-center gap-3"
                >
                  <div className={`w-8 h-8 rounded-lg bg-neutral-800 flex items-center justify-center ${color}`}>
                    {icon}
                  </div>
                  <div className="text-xs">
                    <div className="font-bold text-white">{title}</div>
                    <div className="text-neutral-400">{desc}</div>
                  </div>
                </div>
              ))}
            </div>

            {/* MANDATORY checkbox */}
            <div className="mt-6">
              <label
                htmlFor="ambient-checkbox"
                className={`flex items-start gap-3.5 p-4 rounded-2xl border-2 transition-all cursor-pointer select-none active:scale-[0.99] ${ambientModeConfirmed
                    ? "bg-[#00ff88]/15 border-[#00ff88] text-white shadow-[0_0_25px_rgba(0,255,136,0.2)]"
                    : "bg-neutral-950 border-neutral-700 text-neutral-300 hover:border-neutral-500"
                  }`}
              >
                <div className="relative flex items-center mt-0.5">
                  <input
                    id="ambient-checkbox"
                    type="checkbox"
                    checked={ambientModeConfirmed}
                    onChange={(e) => setAmbientModeConfirmed(e.target.checked)}
                    className="sr-only"
                  />
                  <div
                    className={`w-7 h-7 rounded-lg border-2 flex items-center justify-center transition-all ${ambientModeConfirmed
                        ? "bg-[#00ff88] border-[#00ff88] text-black"
                        : "border-neutral-500 bg-neutral-900"
                      }`}
                  >
                    {ambientModeConfirmed && <Check className="w-5 h-5 stroke-[3]" />}
                  </div>
                </div>
                <div className="text-sm font-semibold leading-snug">
                  <span className="text-white">
                    I have enabled Transparency/Ambient mode on my earphones to hear traffic.
                  </span>
                  <div className="text-xs font-normal text-neutral-400 mt-1">
                    Required to hear approaching vehicles, horns, and emergency sirens.
                  </div>
                </div>
              </label>
            </div>
          </div>

          {/* CTA */}
          <div className="pt-6 pb-2">
            <button
              onClick={handleStartRide}
              disabled={!ambientModeConfirmed}
              type="button"
              className={`w-full py-4 px-6 rounded-2xl font-black text-lg tracking-wider uppercase transition-all flex items-center justify-center gap-3 ${ambientModeConfirmed
                  ? "bg-[#00ff88] text-black shadow-[0_0_35px_rgba(0,255,136,0.6)] active:scale-95 hover:bg-[#00e57a] cursor-pointer"
                  : "bg-neutral-800 text-neutral-500 border border-neutral-700 cursor-not-allowed opacity-60"
                }`}
            >
              <Power className="w-6 h-6 stroke-[2.5]" />
              <span>Start Ride</span>
              <ChevronRight className="w-5 h-5 stroke-[3]" />
            </button>
            <div className="text-center mt-3 text-[11px] font-mono text-neutral-500">
              VoiceSarathi Bengali (bn-IN) · Software Helmet v1.0
            </div>
          </div>
        </div>
      ) : (
        /* =========================================================== */
        /* PHASE 2: ACTIVE RIDER DASHBOARD — HIGH CONTRAST OUTDOOR HUD */
        /* =========================================================== */
        <div className="flex-1 flex flex-col max-w-xl mx-auto w-full p-4 sm:p-5 gap-4">

          {/* ── Top status strip ─────────────────────────────────── */}
          <header className="flex items-center justify-between border-b-2 border-neutral-800 pb-3">
            <div className="flex items-center gap-2">
              <span className="relative flex h-3 w-3">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[#00ff88] opacity-75" />
                <span className="relative inline-flex rounded-full h-3 w-3 bg-[#00ff88]" />
              </span>
              <span className="text-xs font-black tracking-widest text-[#00ff88] uppercase">
                RIDE ACTIVE
              </span>
            </div>

            <div className="flex items-center gap-2">
              <span className="text-xs font-mono text-neutral-300 border border-neutral-700 bg-neutral-900 px-2 py-0.5 rounded-full">
                {currentTime}
              </span>
              <span
                className={`text-[10px] font-mono px-2 py-0.5 rounded-full border ${wakeLockActive
                    ? "bg-emerald-950 border-[#00ff88] text-[#00ff88]"
                    : "bg-neutral-900 border-neutral-700 text-neutral-400"
                  }`}
              >
                {wakeLockActive ? "⚡ WAKE" : "SLEEP"}
              </span>
              <button
                onClick={() => setHighContrastMode(!highContrastMode)}
                title="Toggle sunlight contrast"
                className="p-1 rounded bg-neutral-900 border border-neutral-700"
              >
                <Sun className="w-4 h-4 text-amber-400" />
              </button>
            </div>
          </header>

          {/* ── Speedometer (live GPS) ───────────────────────────── */}
          <Speedometer
            speedLimit={40}
            onSpeedUpdate={setLiveSpeedKmh}
          />

          {/* ── Destination waypoint strip ───────────────────────── */}
          <div className="flex items-center gap-3 p-3 bg-black border-2 border-neutral-800 rounded-2xl">
            <Navigation className="w-5 h-5 text-[#ffee00] flex-shrink-0" />
            <div className="min-w-0">
              <div className="text-[10px] font-mono text-neutral-500 uppercase tracking-widest">
                Next Waypoint
              </div>
              <div className="text-base font-black text-[#ffee00] truncate">
                {currentDestination}
              </div>
            </div>
            {showRoute && (
              <span className="ml-auto text-[10px] font-mono bg-blue-500/20 border border-blue-500/60 text-blue-300 px-2 py-0.5 rounded-full whitespace-nowrap">
                ROUTE ON MAP
              </span>
            )}
          </div>

          {/* ── Leaflet Map ──────────────────────────────────────── */}
          <RiderMap
            center={[22.5726, 88.3639]}
            zoom={13}
            routePolyline={showRoute ? DEMO_ROUTE : undefined}
            height="280px"
          />

          {/* ── Zero-Touch Voice Agent ───────────────────────────── */}
          <VoiceAgent
            defaultLanguage="bn-IN"
            onDestinationExtracted={handleDestinationFound}
            isRideActive={isRideActive}
          />

          {/* ── Footer: SOS + End Ride ───────────────────────────── */}
          <footer className="space-y-3 pb-2">
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => {
                  if (typeof window !== "undefined" && "vibrate" in navigator)
                    navigator.vibrate([200, 100, 200, 100, 400]);
                  alert("Emergency SOS Alert: Beacon broadcasted to emergency contacts.");
                }}
                className="py-3 px-4 rounded-xl bg-rose-950/80 border-2 border-rose-600 text-rose-300 font-bold text-xs uppercase tracking-wider flex items-center justify-center gap-2 active:scale-95 cursor-pointer"
              >
                <AlertOctagon className="w-4 h-4 text-rose-400" />
                <span>SOS Alert</span>
              </button>

              <button
                type="button"
                onClick={handleEndRide}
                className="py-3 px-4 rounded-xl bg-neutral-900 border-2 border-neutral-700 text-white font-extrabold text-xs uppercase tracking-wider flex items-center justify-center gap-2 hover:border-neutral-500 active:scale-95 cursor-pointer"
              >
                <Power className="w-4 h-4 text-rose-500" />
                <span>End Ride</span>
              </button>
            </div>

            <div className="flex items-center justify-center gap-2 text-[10px] font-mono text-neutral-500 text-center">
              <ShieldCheck className="w-3.5 h-3.5 text-[#00ff88]" />
              <span>VoiceSarathi Software Helmet Guard Active</span>
            </div>
          </footer>
        </div>
      )}
    </main>
  );
}
